import{c as a,Q as t,j as o,m as i}from"./chunks/framework.D55kK6e8.js";const p=JSON.parse('{"title":"实时通知","description":"","frontmatter":{},"headers":[],"relativePath":"guide/websocket.md","filePath":"guide/websocket.md"}'),l={name:"guide/websocket.md"};function r(d,e,s,c,n,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="实时通知" tabindex="-1">实时通知 <a class="header-anchor" href="#实时通知" aria-label="Permalink to &quot;实时通知&quot;">​</a></h1><p>系统使用 WebSocket 实现实时通信，确保工单状态的即时同步。</p><h2 id="websocket-功能" tabindex="-1">WebSocket 功能 <a class="header-anchor" href="#websocket-功能" aria-label="Permalink to &quot;WebSocket 功能&quot;">​</a></h2><ul><li><strong>连接状态显示</strong> - 在创建工单页面显示 WebSocket 连接状态</li><li><strong>新工单通知</strong> - 当有新工单创建时，向所有在线用户推送通知</li><li><strong>状态更新通知</strong> - 工单状态变更时实时通知相关用户</li></ul><h2 id="事件类型" tabindex="-1">事件类型 <a class="header-anchor" href="#事件类型" aria-label="Permalink to &quot;事件类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事件名</th><th>说明</th></tr></thead><tbody><tr><td><code>ticket_created</code></td><td>新工单创建</td></tr><tr><td><code>ticket_updated</code></td><td>工单信息更新</td></tr><tr><td><code>ticket_status_changed</code></td><td>工单状态变更</td></tr></tbody></table><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><p>WebSocket 连接地址通常与 API 地址一致，使用 <code>ws://</code> 或 <code>wss://</code> 协议：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ws://your-backend:port/ws</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="使用场景" tabindex="-1">使用场景 <a class="header-anchor" href="#使用场景" aria-label="Permalink to &quot;使用场景&quot;">​</a></h2><h3 id="创建工单页面" tabindex="-1">创建工单页面 <a class="header-anchor" href="#创建工单页面" aria-label="Permalink to &quot;创建工单页面&quot;">​</a></h3><p>在创建工单时，WebSocket 会：</p><ol><li>建立连接并显示状态指示器</li><li>提交工单后通过 WebSocket 广播</li><li>其他在线用户会收到新工单通知</li></ol><h3 id="工单详情页面" tabindex="-1">工单详情页面 <a class="header-anchor" href="#工单详情页面" aria-label="Permalink to &quot;工单详情页面&quot;">​</a></h3><p>在查看工单详情时，WebSocket 会：</p><ol><li>监听工单更新事件</li><li>收到更新时自动刷新页面数据</li><li>显示更新提示信息</li></ol><h2 id="断线重连" tabindex="-1">断线重连 <a class="header-anchor" href="#断线重连" aria-label="Permalink to &quot;断线重连&quot;">​</a></h2><p>系统内置断线检测和自动重连机制：</p><ul><li>定期检查连接状态（每 5 秒）</li><li>连接断开时显示提示</li><li>自动尝试重新连接</li></ul>',19)])])}const u=a(l,[["render",r]]);export{p as __pageData,u as default};
